document.addEventListener('DOMContentLoaded',()=>{const t=document.querySelector('.menu-toggle'),n=document.querySelector('.nav');t?.addEventListener('click',()=>{const open=n.classList.toggle('open');t.setAttribute('aria-expanded',open);});document.querySelectorAll('.nav-drop>button').forEach(b=>b.addEventListener('click',e=>{if(innerWidth>1000)return;e.preventDefault();const d=b.parentElement;document.querySelectorAll('.nav-drop').forEach(x=>x!==d&&x.classList.remove('open'));d.classList.toggle('open');b.setAttribute('aria-expanded',d.classList.contains('open'));}));const f=document.querySelector('[data-project-form]');f?.addEventListener('submit',e=>{e.preventDefault();if(!f.checkValidity()){f.reportValidity();return}const data=new FormData(f),subject=encodeURIComponent(`Website inquiry: ${data.get('project')||'New project'}`),body=encodeURIComponent(`Name: ${data.get('name')}\nEmail: ${data.get('email')}\nOrganization: ${data.get('organization')}\nProject type: ${data.get('project')}\nBudget range: ${data.get('budget')}\nTimeline: ${data.get('timeline')}\n\nProject details:\n${data.get('message')}`);const s=document.querySelector('.form-status');s.textContent='Your email draft is ready. Please send it to start the conversation.';window.location.href=`mailto:info@ashitconsulting.ca?subject=${subject}&body=${body}`;});});
document.addEventListener('DOMContentLoaded',()=>{const els=document.querySelectorAll('[data-reveal]');if(!els.length||!('IntersectionObserver'in window)||matchMedia('(prefers-reduced-motion: reduce)').matches){els.forEach(e=>e.classList.add('in'));return}const io=new IntersectionObserver(es=>es.forEach(e=>{if(!e.isIntersecting)return;const sib=[...e.target.parentElement.children].filter(x=>x.hasAttribute('data-reveal'));e.target.style.transitionDelay=`${Math.min(sib.indexOf(e.target),5)*40}ms`;e.target.classList.add('in');io.unobserve(e.target)}),{rootMargin:'0px 0px -8% 0px',threshold:.12});els.forEach(e=>io.observe(e))});
